"use client";

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva } from "class-variance-authority";
import {
  type ButtonHTMLAttributes,
  type CSSProperties,
  cloneElement,
  forwardRef,
  isValidElement,
  type KeyboardEvent,
  type PointerEvent,
  type ReactElement,
  type Ref,
  type RefCallback,
  type SyntheticEvent,
  use,
  useCallback,
  useRef,
} from "react";
import { cn } from "../lib/cn.js";
import { animate, dur, ease, spring, useReducedMotion } from "../motion/index.js";
import { touchTarget } from "./touch.js";

// Generated by shadcn (Base UI, Mira) and rewritten to the annotated-scoresheet tokens
// (packages/ui/DESIGN.md, "Interaction states"). Hover changes tone one step down the ladder
// (`--surface-hover`), never position (M5).
export const buttonVariants = cva(
  [
    "relative inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap select-none",
    "rounded-field border font-sans font-medium",
    "transition-colors duration-(--dur-quick) ease-out",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink",
    "disabled:pointer-events-none aria-disabled:pointer-events-none",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
    touchTarget,
  ],
  {
    variants: {
      variant: {
        primary: [
          "border-ink bg-ink text-on-ink hover:border-ink-soft hover:bg-ink-soft",
          "disabled:border-well disabled:bg-well disabled:text-ink-faint",
        ],
        outline: [
          "border-rule-strong bg-transparent text-ink hover:bg-(--surface-hover)",
          "active:bg-well active:inset-ring-1 active:inset-ring-rule-strong",
          "disabled:border-rule disabled:text-ink-faint",
        ],
        quiet: [
          "border-transparent bg-transparent text-ink-soft hover:bg-(--surface-hover) hover:text-ink",
          "active:bg-well active:inset-ring-1 active:inset-ring-rule-strong",
          "disabled:text-ink-faint",
        ],
        // Destructive actions are ink-outlined, never red: red marks chess mistakes and form
        // errors only (DESIGN.md, "Direction"). The severity is carried by a heavier ink edge, 700
        // weight and an explicit verb ("Delete account").
        danger: [
          "border-2 border-ink bg-transparent font-bold text-ink hover:bg-(--surface-hover)",
          "active:bg-well active:inset-ring-1 active:inset-ring-rule-strong",
          "disabled:border disabled:border-rule disabled:font-medium disabled:text-ink-faint",
        ],
      },
      size: {
        sm: "h-8 px-3 text-sm [&_svg]:size-4",
        md: "h-10 px-4 text-base [&_svg]:size-5",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  },
);

export interface ButtonProps extends ButtonHTMLAttributes<HTMLElement> {
  variant?: "primary" | "outline" | "quiet" | "danger";
  size?: "sm" | "md";
  /** Render the single child element (a link, say) with the button's look and press. */
  asChild?: boolean;
}

const PRESS_SCALE = 0.97;

/**
 * The pen-press (choreography 7): scale 0.97 over `dur.instant`, released on `land` with its small
 * rebound. Transform only (M9). Under reduced motion there is no movement (M10).
 */
function usePenPress() {
  const reduced = useReducedMotion();
  const held = useRef(false);

  const press = useCallback(
    (el: Element) => {
      if (reduced || held.current) return;
      held.current = true;
      animate(el, { scale: PRESS_SCALE }, { duration: dur.instant, ease: [...ease.out] });
    },
    [reduced],
  );
  const release = useCallback((el: Element) => {
    if (!held.current) return;
    held.current = false;
    animate(el, { scale: 1 }, spring.land);
  }, []);
  return { press, release };
}

function composeRefs<T>(...refs: (Ref<T> | undefined)[]): RefCallback<T> {
  return (node) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as { current: T | null }).current = node;
    }
  };
}

type Handler<E extends SyntheticEvent> = ((event: E) => void) | undefined;

/**
 * Calls the first handler, then the second unless the first called preventDefault. The first
 * always runs, even for an event that arrives already prevented.
 */
function chain<E extends SyntheticEvent>(
  first: Handler<E>,
  second: Handler<E>,
): (event: E) => void {
  return (event) => {
    first?.(event);
    if (!event.defaultPrevented) second?.(event);
  };
}

type ChildProps = Record<string, unknown> & { className?: string; ref?: Ref<HTMLElement> };

const REACT_LAZY = Symbol.for("react.lazy");
type Lazy = { $$typeof: symbol; _payload: PromiseLike<unknown> };

const isLazy = (v: unknown): v is Lazy =>
  typeof v === "object" &&
  v !== null &&
  (v as { $$typeof?: unknown }).$$typeof === REACT_LAZY &&
  typeof (v as { _payload?: { then?: unknown } })._payload?.then === "function";

/**
 * A server component's child reaches a client component during SSR as a lazy reference (React
 * Flight), not an element, while the browser may already hold the element. Unwrapping it the way
 * Radix Slot does keeps `asChild` rendering the same element on both sides (bug hunt B3/I4).
 */
function unwrapLazy(value: unknown): unknown {
  let out = value;
  while (isLazy(out)) out = use(out._payload);
  return out;
}

export const Button = forwardRef<HTMLElement, ButtonProps>(function Button(
  {
    className,
    variant,
    size,
    asChild = false,
    children: rawChildren,
    onPointerDown,
    onPointerUp,
    onPointerLeave,
    onPointerCancel,
    onKeyDown,
    onKeyUp,
    ...props
  },
  ref,
) {
  const { press, release } = usePenPress();
  const children = (asChild ? unwrapLazy(rawChildren) : rawChildren) as ButtonProps["children"];
  const classes = cn(buttonVariants({ variant, size }), className);

  const releaseOn = (e: SyntheticEvent<HTMLElement>) => release(e.currentTarget);
  const own = {
    onPointerDown: chain<PointerEvent<HTMLElement>>(onPointerDown, (e) => {
      if (e.button === 0) press(e.currentTarget);
    }),
    onPointerUp: chain<PointerEvent<HTMLElement>>(onPointerUp, releaseOn),
    onPointerLeave: chain<PointerEvent<HTMLElement>>(onPointerLeave, releaseOn),
    onPointerCancel: chain<PointerEvent<HTMLElement>>(onPointerCancel, releaseOn),
    onKeyDown: chain<KeyboardEvent<HTMLElement>>(onKeyDown, (e) => {
      if (!e.repeat && (e.key === " " || e.key === "Enter")) press(e.currentTarget);
    }),
    onKeyUp: chain<KeyboardEvent<HTMLElement>>(onKeyUp, releaseOn),
  };

  // asChild keeps the child's own element and role (a link stays a link), so it skips Base UI's
  // button behaviour and only takes the look and the press. Props merge as Radix Slot merges them:
  // handlers both run (the child's first, ours unless it called preventDefault), class names and
  // styles combine (the child's style wins per property), refs compose, and any other prop the
  // child sets itself wins over the Button's.
  if (asChild && isValidElement(children)) {
    const child = children as ReactElement<ChildProps>;
    const childProps = child.props;
    const merged: Record<string, unknown> = {};
    const buttonProps: Record<string, unknown> = { ...props, ...own };
    for (const [name, value] of Object.entries(buttonProps)) {
      const childValue = childProps[name];
      if (/^on[A-Z]/.test(name) && typeof value === "function") {
        merged[name] =
          typeof childValue === "function"
            ? chain(childValue as Handler<SyntheticEvent>, value as Handler<SyntheticEvent>)
            : value;
      } else if (name === "style") {
        merged.style = { ...(value as CSSProperties), ...(childProps.style as CSSProperties) };
      } else if (!(name in childProps)) {
        merged[name] = value;
      }
    }
    return cloneElement(child, {
      ...merged,
      ref: composeRefs(childProps.ref, ref),
      "data-slot": "button",
      className: cn(classes, childProps.className),
    });
  }

  return (
    <ButtonPrimitive
      ref={ref}
      data-slot="button"
      className={classes}
      {...(props as ButtonPrimitive.Props)}
      {...own}
    >
      {children}
    </ButtonPrimitive>
  );
});
